WITH flattened AS (SELECT id, plan, effective_from, currency, val FROM price_tiers LATERAL VIEW EXPLODE(tier_prices) t AS val), metrics AS (SELECT id, plan, AVG(val) OVER (PARTITION BY plan) AS plan_avg_val, PERCENT_RANK() OVER (ORDER BY val DESC) AS val_percent_rank, PERCENT_RANK() OVER (PARTITION BY plan ORDER BY val NULLS FIRST) AS val_percent_rank_2, MIN(val) OVER (PARTITION BY currency) AS currency_min_val FROM flattened), scored AS (SELECT *, RANK() OVER (PARTITION BY plan ORDER BY currency_min_val DESC NULLS LAST) AS currency_min_val_rank, STDDEV_SAMP(val_percent_rank) OVER (PARTITION BY plan) AS plan_stddev_samp_val_percent_rank, CUME_DIST() OVER (PARTITION BY plan ORDER BY val_percent_rank_2) AS val_percent_rank_2_cume_dist, PERCENT_RANK() OVER (ORDER BY val_percent_rank_2 NULLS FIRST) AS val_percent_rank_2_percent_rank, RANK() OVER (PARTITION BY plan ORDER BY currency_min_val DESC NULLS LAST) AS currency_min_val_rank_2 FROM metrics WHERE currency_min_val != 62), filtered AS (SELECT id, plan, plan_avg_val, val_percent_rank_2, currency_min_val, plan_stddev_samp_val_percent_rank, val_percent_rank_2_cume_dist, val_percent_rank_2_percent_rank, currency_min_val_rank_2, ROUND(val_percent_rank * 1.15, 2) AS val_percent_rank_adjusted FROM scored WHERE plan = 'basic'), base AS (SELECT *, val_percent_rank_2 - currency_min_val_rank_2 AS val_percent_rank_2_minus_currency_min_val_rank_2, ROUND(plan_avg_val * 1.15, 2) AS adjusted_plan_avg_val FROM filtered WHERE val_percent_rank_2_cume_dist >= 0.73), grouped AS (SELECT CASE WHEN val_percent_rank_2_percent_rank >= 0.68 THEN 'PREMIUM' ELSE 'STANDARD' END AS val_percent_rank_2_percent_rank_tier, plan, COUNT(DISTINCT id) AS distinct_ids, MAX(currency_min_val_rank_2) AS max_currency_min_val_rank_2, MAX(val_percent_rank_2_cume_dist) FILTER (WHERE plan = 'pro') AS pro_max_val_percent_rank_2_cume_dist, PERCENTILE_APPROX(val_percent_rank_2_minus_currency_min_val_rank_2, ARRAY(0.25, 0.5, 0.75)) AS val_percent_rank_2_minus_currency_min_val_rank_2_quartiles, ROUND(AVG(val_percent_rank_2_minus_currency_min_val_rank_2), 2) AS avg_val_percent_rank_2_minus_currency_min_val_rank_2, GROUPING_ID() AS grouping_id FROM base GROUP BY GROUPING SETS ((CASE WHEN val_percent_rank_2_percent_rank >= 0.68 THEN 'PREMIUM' ELSE 'STANDARD' END, plan), (CASE WHEN val_percent_rank_2_percent_rank >= 0.68 THEN 'PREMIUM' ELSE 'STANDARD' END))) SELECT plan, max_currency_min_val_rank_2, pro_max_val_percent_rank_2_cume_dist, val_percent_rank_2_minus_currency_min_val_rank_2_quartiles, avg_val_percent_rank_2_minus_currency_min_val_rank_2 FROM grouped ORDER BY plan DESC NULLS FIRST
